export const SEGMENTS = [
  { scene: 2, text: "Mười lăm tuổi, cái tuổi bây giờ người ta còn lo thi vào lớp mười. Nguyễn Ánh thì lo chuyện khác: sống sót. Cả dòng họ bị truy sát, những người thân cuối cùng lần lượt ngã xuống. Chỉ mình cậu chạy thoát.", cue: "somber" },
  { scene: 3, text: "Hai mươi lăm năm sau, cũng chính cậu thiếu niên ấy bước lên ngai vàng, trở thành hoàng đế.", cue: "curious" },
  { scene: 4, text: "Nghe thì giống truyện cổ tích. Nhưng con đường tới ngai vàng không trải thảm đỏ. Nó trải bằng nước sông, bùn lầy, và rất nhiều lần phải bỏ chạy.", cue: "curious" },
  { scene: 5, text: "Muốn hiểu Nguyễn Ánh, phải nhìn vùng đất cậu đang trú thân. Gia Định cuối thế kỷ 18 là xứ của sông rạch và ghe thuyền. Ai giữ được đường sông, người đó giữ được quyền lực. Và dòng họ Nguyễn đang tuột dần khỏi tay cả hai.", cue: "neutral" },
  { scene: 6, text: "Đối thủ của họ là Tây Sơn. Sau những thắng lợi liên tiếp, quân Tây Sơn tiến sâu về phía Nam. Còn phe Nguyễn thì giống một ngôi nhà vừa cháy mái vừa cãi nhau trong bếp: ngoài có giặc, trong có chia rẽ.", cue: "tense" },
  { scene: 7, text: "Nguyễn Ánh sinh năm 1762. Năm 1777, cậu mới khoảng mười lăm tuổi. Người lớn bàn chuyện sống còn của gia tộc, còn cậu chưa có tiếng nói quyết định. Nhưng chiến tranh thì chẳng chờ ai đủ lớn.", cue: "neutral" },
  { scene: 8, text: "Rồi tin dữ tới bằng đường sông, nhanh hơn mọi lời trấn an. Quân Tây Sơn đang đến. Những người hôm qua còn tin thành lũy giữ được Gia Định, hôm nay phải tính đường rút. Với Nguyễn Ánh, nơi trú thân cũng bắt đầu lung lay.", cue: "tense" },
  { scene: 9, text: "Năm 1777, chiến thuyền Tây Sơn nối nhau ngược dòng. Ở xứ sông nước, mất đường sông cũng như mất luôn cánh cửa thoát hiểm. Lối thoát của Nguyễn Ánh hẹp lại từng ngày.", cue: "tense" },
  { scene: 10, text: "Các đồn phòng thủ liên tiếp chịu sức ép. Những tuyến sông từng chở lúa gạo, giờ thành chiến tuyến. Chỉ một trận thua là liên lạc giữa các nhóm quân có thể đứt. Ở tuổi mười lăm, Nguyễn Ánh được nhìn tận mắt một thế trận sụp nhanh thế nào.", cue: "tense" },
  { scene: 11, text: "Đồn mất dần, người phe Nguyễn phải bỏ nơi đóng quân. Đây không phải cuộc rút lui có bản đồ và kế hoạch đẹp đẽ. Đó là những quyết định gấp gáp, đồ đạc gói vội, và trong dòng người ấy có Nguyễn Ánh.", cue: "somber" },
  { scene: 12, text: "Các nhân vật chủ chốt tản về miền Tây. Định Vương Nguyễn Phúc Thuần, chú của Nguyễn Ánh, tìm đường tới Long Xuyên. Cậu đi theo những người thân còn lại, giữa lúc tình thế mỗi ngày một ngặt nghèo.", cue: "somber" },
  { scene: 13, text: "Tháng chín năm 1777, Tân Chính Vương Nguyễn Phúc Dương bị bắt và bị giết cùng những người theo hầu. Với Nguyễn Ánh, đó không chỉ là một dòng trong sử sách. Đó là thêm một người thân mất đi, thêm một trụ cột của chính quyền chúa Nguyễn đổ xuống.", cue: "somber" },
  { scene: 14, text: "Tháng mười, quân Tây Sơn truy kích tới Long Xuyên, nơi Định Vương đang trú. Những người quanh ông không còn đủ sức xoay chuyển tình thế. Còn Nguyễn Ánh đứng trước nguy cơ mất nốt những người thân cuối cùng.", cue: "tense" },
  { scene: 15, text: "Ngày 18 tháng 10 năm 1777, Định Vương bị giết cùng một số thân thuộc và tướng lĩnh. Theo biên niên sử được các nhà nghiên cứu dẫn lại, Nguyễn Ánh, khi ấy mười lăm tuổi, là người chạy thoát.", cue: "somber" },
  { scene: 16, text: "Sử sách không ghi lại từng bước chân của cuộc đào thoát. Nhưng thử đặt mình vào chỗ cậu: mười lăm tuổi, mất người thân, phía sau là quân truy đuổi. Lúc ấy, im lặng có khi là cách duy nhất để sống.", cue: "somber" },
  { scene: 17, text: "Ở đồng bằng chằng chịt sông rạch, địa hình làm khó người đi, nhưng cũng giấu được người trốn. Nước, lau sậy và những con rạch nhỏ, thứ cản bước quân lính, lại thành đường sống của Nguyễn Ánh.", cue: "tense" },
  { scene: 18, text: "Không có câu nói nào được xác nhận là của Nguyễn Ánh trong những ngày ấy. Không lời thề, không tuyên ngôn. Điều sử liệu cho thấy đơn giản hơn nhiều: cậu đã không bị bắt. Đôi khi, một câu chuyện lớn bắt đầu chỉ bằng việc còn sống.", cue: "somber" },
  { scene: 19, text: "Khoảng một tháng sau, Nguyễn Ánh xuất hiện trở lại ở Long Xuyên. Đừng vội gọi đó là chiến thắng. Nó chỉ cho thấy cuộc chiến chưa kết thúc, và vẫn còn người sẵn sàng đi theo cậu.", cue: "hopeful" },
  { scene: 20, text: "Những người còn trung thành bắt đầu tụ lại quanh Nguyễn Ánh. Chưa có triều đình, chưa có kinh đô, chỉ có vài ngọn đèn dầu và một nhóm người chưa chịu bỏ cuộc. Nhưng cuộc phản công nào cũng bắt đầu từ những gì còn sót lại.", cue: "hopeful" },
  { scene: 21, text: "Tháng mười một năm 1777, Nguyễn Ánh cùng một số tướng cũ tiến về Sa Đéc. Từ những chỗ trú ẩn rải rác, phe Nguyễn nối lại liên lạc, như người ta vá từng mắt lưới rách trước khi thả xuống sông lần nữa.", cue: "neutral" },
  { scene: 22, text: "Những cái tên như Đỗ Thanh Nhơn và Lê Văn Quân gắn với việc tái tổ chức lực lượng quanh Nguyễn Ánh. Lúc này, thứ quý nhất không phải kinh đô hay ngai vàng. Mà là người, là thuyền, và những tuyến liên lạc chưa bị cắt.", cue: "neutral" },
  { scene: 23, text: "Cuối năm 1777, lực lượng của Nguyễn Ánh đánh úp Long Hồ. So với việc lấy lại cả Gia Định, đó chỉ là một bước nhỏ. Nhưng với một nhóm người vừa chạy trốn, chuyển từ bị đuổi sang đi đánh đã là một cú lật đáng kể.", cue: "tense" },
  { scene: 24, text: "Đầu năm 1778, phe Nguyễn từng bước lấy lại một phần Gia Định, và Nguyễn Ánh, mới khoảng mười sáu tuổi, được các tướng tôn lên vị trí chỉ huy cao hơn. Nhưng chưa phải lúc ăn mừng. Cuộc đào thoát không mang lại hòa bình. Nó mở ra một vòng xoáy mới: thua, chạy, gom người, rồi quay lại. Và cậu thiếu niên ấy sẽ còn phải chạy nhiều lần nữa.", cue: "dramatic" },
];
